param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$texts=[Collections.Generic.List[object]]::new();$texts.Add([int[]]@());foreach($unit in 0..255){$texts.Add([int[]]@($unit))};foreach($first in @(0,65,0x80,0x90,0xbf,0xc2,0xe0,0xed,0xf0,0xf4,0xff)){foreach($second in @(0,65,0x80,0x90,0xbf,0xc2,0xe0,0xed,0xf0,0xf4,0xff)){$texts.Add([int[]]@($first,$second))}};foreach($first in @(0x80,0xe2,0xf0)){foreach($second in @(0x80,0xe2,0xf0)){foreach($third in @(0x80,0xe2,0xf0)){$texts.Add([int[]]@($first,$second,$third))}}};foreach($v in @(@(0xc2,0x80),@(0xdf,0xbf),@(0xe0,0xa0,0x80),@(0xed,0x9f,0xbf),@(0xee,0x80,0x80),@(0xef,0xbf,0xbf),@(0xf0,0x90,0x80,0x80),@(0xf4,0x8f,0xbf,0xbf),@(0xed,0xa0,0x80),@(0xf4,0x90,0x80,0x80),@(65,0xe2,0x82,0xac,66),@(65,0xf0,0x90,0x80,0x80,66),@(0xe2,0x82),@(0xf0,0x90,0x80),@(0xc0,0x80),@(0xe0,0x80,0x80),@(0xf0,0x80,0x80,0x80))){$texts.Add([int[]]$v)}
$configs=@();foreach($emit in @($false,$true)){foreach($strict in @($false,$true)){$configs+=@([ordered]@{emit=$emit;strict=$strict;replacement=$null})}};foreach($replacement in @(@(),@(65,66),@(0xd800,0xdc00))){$configs+=@([ordered]@{emit=$false;strict=$false;replacement=[int[]]$replacement})}
$profiles=@();foreach($config in $configs){$encoding=[Text.Encoding]([Text.UTF8Encoding]::new([bool]$config.emit,[bool]$config.strict)).Clone();if($null -ne $config.replacement){$encoding.DecoderFallback=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$config.replacement))};$rows=[Collections.Generic.List[object]]::new()
 foreach($sourceId in 0..($texts.Count-1)){$text=[byte[]][int[]]$texts[$sourceId];foreach($split in 0..$text.Length){foreach($flushSecond in @($false,$true)){
  $decoder=$encoding.GetDecoder();$steps=@();foreach($block in 0..2){if($block -eq 0){$units=[byte[]]::new($split);[Array]::Copy($text,0,$units,0,$split);$flush=$false}elseif($block -eq 1){$units=[byte[]]::new($text.Length-$split);[Array]::Copy($text,$split,$units,0,$units.Length);$flush=$flushSecond}else{$units=[byte[]]@();$flush=$true}
   foreach($operation in @('Count','Chars')){$destination=$null;try{if($operation -eq 'Count'){$n=$decoder.GetCharCount($units,0,$units.Length,$flush)}else{$destination=[char[]]::new(24);[Array]::Fill[char]($destination,[char]99);$n=$decoder.GetChars($units,0,$units.Length,$destination,1,$flush)};$result=[ordered]@{ok=$true;count=$n}}catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$result=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.DecoderFallbackException]){$result.unknownBytes=[int[]]$e.BytesUnknown;$result.index=$e.Index}}
    $steps+=@([ordered]@{operation=$operation;block=$block;flush=$flush;result=$result;after=$(if($null -eq $destination){$null}else{,[int[]]$destination})})
   }
  };$rows.Add([ordered]@{sourceId=$sourceId;split=$split;flushSecond=$flushSecond;steps=$steps})
 }}}
 $probe=$encoding.GetDecoder();$profiles+=@([ordered]@{config=$config;freshInstances=-not [object]::ReferenceEquals($probe,$encoding.GetDecoder());fallbackSharedWithEncoding=[object]::ReferenceEquals($probe.Fallback,$encoding.DecoderFallback);rows=$rows.ToArray()})
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();byteInputs=$texts.ToArray();profiles=$profiles;qualification='SELECTED_STATEFUL_UTF8_DECODER_ARRAY_PARTITIONS_ONLY; CAPACITY_CUSTOM_BUFFERS_CONVERT_SPAN_POINTER_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS pinned stateful UTF-8 decoder partition capture'
